window.VO = [{"id":"n01b","text":"You get one chance to hear what was in that box, so remember every word.","at":0.24,"t0":0.12,"t1":4.35},{"id":"c00","text":"Slowly, madam. Everything that was in it.","at":10.9,"t0":5.45,"t1":8.35},{"id":"s01","text":"My box! Milk, sugar, ginger, cardamom, the cups, the strainer, the biscuits, my kettle, the spoons!","at":17.3,"t0":8.65,"t1":13.995},{"id":"n03","text":"Did she say tea?","at":28.69,"t0":14.345,"t1":15.42},{"id":"n04","text":"She never said it.","at":34.04,"t0":17.02,"t1":18.14},{"id":"c01","text":"The kettle, the spoons, and the tea.","at":36.88,"t0":18.44,"t1":20.99},{"id":"n10c","text":"Every word she did say was about tea, so that's what stuck, in your memory and in his notebook.","at":43.38,"t0":21.69,"t1":27.155},{"id":"n11","text":"Psychologists have tested this since 1959, and with lists like hers, most people say they heard the word that wasn't there.","at":55.91,"t0":27.955,"t1":35.25},{"id":"t01","text":"It's for her stall!","at":75.3,"t0":37.65,"t1":38.795},{"id":"c02","text":"Exactly.","at":78.09,"t0":39.045,"t1":40.045},{"id":"t02s","text":"I bring it every morning, sir!","at":80.69,"t0":40.345,"t1":41.885},{"id":"s02b","text":"He's my tea man!","at":85.77,"t0":42.885,"t1":44.385},{"id":"c03","text":"You nodded.","at":89.37,"t0":44.685,"t1":45.635},{"id":"n07b","text":"Even he went looking for the tea.","at":93.27,"t0":46.635,"t1":48.39},{"id":"n08","text":"If you said no, name the nine things she did say.","at":98.38,"t0":49.19,"t1":51.89}];
